    std::vector<uint8_t> Serialize(const LiveRoomStreamSnapshot& value)
    {
        Wire::ProtoWriter writer;
        EncodeTo(value, writer);
        return writer.TakeBuffer();
    }

    bool Deserialize(LiveRoomStreamSnapshot& value, const uint8_t* data, size_t size)
    {
        value = LiveRoomStreamSnapshot{};
        Wire::ProtoReader reader(data, size);
        return DecodeFrom(value, reader);
    }

    void EncodeTo(const LiveTournamentStreamSnapshot& value, Wire::ProtoWriter& writer)
    {
        if (!value.TournamentId.empty())
            writer.WriteStringField(1, value.TournamentId);

        if (value.Sequence != 0)
            writer.WriteVarintField(2, value.Sequence);

        if (value.ServerTimeUnixMs != 0)
            writer.WriteVarintField(3, uint64_t(int64_t(value.ServerTimeUnixMs)));

        for (const auto& item : value.Rooms)
        {
            Wire::ProtoWriter sub;
            EncodeTo(item, sub);
            writer.WriteBytesField(4, sub.Buffer().data(), sub.Buffer().size());
        }
    }

    bool DecodeFrom(LiveTournamentStreamSnapshot& value, Wire::ProtoReader& reader)
    {
        uint32_t fieldNumber = 0;
        uint32_t wireType = 0;
        while (reader.ReadTag(fieldNumber, wireType))
        {
            switch (fieldNumber)
            {
            case 1:
            {
                if (wireType == 2)
                {
                    if (!reader.ReadString(value.TournamentId))
                        return false;
                }
                else if (!reader.SkipField(wireType))
                    return false;
                break;
            }
            case 2:
            {
                if (wireType == 0)
                {
                    uint64_t raw = 0;
                    if (!reader.ReadVarint(raw))
                        return false;
                    value.Sequence = raw;
                }
                else if (!reader.SkipField(wireType))
                    return false;
                break;
            }
            case 3:
            {
                if (wireType == 0)
                {
                    uint64_t raw = 0;
                    if (!reader.ReadVarint(raw))
                        return false;
                    value.ServerTimeUnixMs = int64_t(raw);
                }
                else if (!reader.SkipField(wireType))
                    return false;
                break;
            }
            case 4:
            {
                if (wireType == 2)
                {
                    const uint8_t* subData = nullptr;
                    size_t subSize = 0;
                    if (!reader.ReadLengthDelimited(subData, subSize))
                        return false;
                    Wire::ProtoReader subReader(subData, subSize);
                    if (!DecodeFrom(value.Rooms.emplace_back(), subReader))
                        return false;
                }
                else if (!reader.SkipField(wireType))
                    return false;
                break;
            }
            default:
            {
                if (!reader.SkipField(wireType))
                    return false;
                break;
            }
            }
        }
        return !reader.HasError();
    }

    std::vector<uint8_t> Serialize(const LiveTournamentStreamSnapshot& value)
    {
        Wire::ProtoWriter writer;
        EncodeTo(value, writer);
        return writer.TakeBuffer();
    }

    bool Deserialize(LiveTournamentStreamSnapshot& value, const uint8_t* data, size_t size)
    {
        value = LiveTournamentStreamSnapshot{};
        Wire::ProtoReader reader(data, size);
        return DecodeFrom(value, reader);
    }
